-- Optional product modules and later runtime additions can be absent from
-- older Python catalogs. They are added only to the Rust-owned copy.
CREATE TABLE IF NOT EXISTS memory_contexts (task_id VARCHAR(100) PRIMARY KEY NOT NULL, run_id VARCHAR(32) NOT NULL, task_key VARCHAR(64) NOT NULL, agent_id VARCHAR(32) NOT NULL, version INTEGER NOT NULL, compressed BOOLEAN NOT NULL, context JSON NOT NULL, updated_at VARCHAR(40) NOT NULL);
CREATE TABLE IF NOT EXISTS runtime_approvals (id VARCHAR(64) PRIMARY KEY NOT NULL, run_id VARCHAR(32) NOT NULL, task_key VARCHAR(64) NOT NULL, agent_id VARCHAR(32) NOT NULL, connection_id VARCHAR(64) NOT NULL, request_id JSON NOT NULL, thread_id VARCHAR(100) NOT NULL, turn_id VARCHAR(100) NOT NULL, item_id VARCHAR(100) NOT NULL, kind VARCHAR(100) NOT NULL, payload JSON NOT NULL, digest VARCHAR(64) NOT NULL, status VARCHAR(32) NOT NULL, decision JSON NOT NULL, error TEXT NOT NULL, created_at VARCHAR(40) NOT NULL, updated_at VARCHAR(40) NOT NULL);
CREATE INDEX IF NOT EXISTS ix_memory_contexts_run_id ON memory_contexts(run_id);
CREATE INDEX IF NOT EXISTS ix_runtime_approvals_run_id ON runtime_approvals(run_id);
CREATE INDEX IF NOT EXISTS ix_runtime_approvals_status ON runtime_approvals(status);
CREATE TABLE IF NOT EXISTS design_assets (id VARCHAR(32) PRIMARY KEY NOT NULL, kind VARCHAR(24) NOT NULL, latest_version INTEGER NOT NULL, published_version INTEGER, lock_version INTEGER NOT NULL, created_by VARCHAR(32) NOT NULL, created_at VARCHAR(40) NOT NULL);
CREATE TABLE IF NOT EXISTS design_revisions (id VARCHAR(80) PRIMARY KEY NOT NULL, asset_id VARCHAR(32) NOT NULL, version INTEGER NOT NULL, name VARCHAR(120) NOT NULL, config JSON NOT NULL, digest VARCHAR(64) NOT NULL, source VARCHAR(24) NOT NULL, generation JSON NOT NULL, status VARCHAR(24) NOT NULL, created_by VARCHAR(32) NOT NULL, created_at VARCHAR(40) NOT NULL, published_by VARCHAR(32) NOT NULL, published_at VARCHAR(40) NOT NULL, revoked_by VARCHAR(32) NOT NULL, revoked_at VARCHAR(40) NOT NULL, UNIQUE(asset_id,version));
CREATE TABLE IF NOT EXISTS design_audit (id VARCHAR(32) PRIMARY KEY NOT NULL, asset_id VARCHAR(32) NOT NULL, version INTEGER NOT NULL, digest VARCHAR(64) NOT NULL, action VARCHAR(24) NOT NULL, actor VARCHAR(32) NOT NULL, comment TEXT NOT NULL, created_at VARCHAR(40) NOT NULL);
CREATE TABLE IF NOT EXISTS execution_permissions (id VARCHAR(64) PRIMARY KEY NOT NULL, run_id VARCHAR(32) NOT NULL, task_key VARCHAR(64) NOT NULL, agent_id VARCHAR(32) NOT NULL, decision_id VARCHAR(64) NOT NULL, digest VARCHAR(64) NOT NULL, command VARCHAR(4000) NOT NULL, network BOOLEAN NOT NULL, paths JSON NOT NULL, reason VARCHAR(2000) NOT NULL, status VARCHAR(24) NOT NULL, reviewed_by VARCHAR(80) NOT NULL, review_kind VARCHAR(20) NOT NULL, review_comment VARCHAR(2000) NOT NULL, result JSON NOT NULL, created_at VARCHAR(40) NOT NULL, updated_at VARCHAR(40) NOT NULL);
CREATE TABLE IF NOT EXISTS model_asset_revisions (id VARCHAR(80) PRIMARY KEY NOT NULL, model_id VARCHAR(32) NOT NULL, version INTEGER NOT NULL, config JSON NOT NULL, actor VARCHAR(32) NOT NULL, created_at VARCHAR(40) NOT NULL);
CREATE TABLE IF NOT EXISTS model_benchmarks (id VARCHAR(32) PRIMARY KEY NOT NULL, model_id VARCHAR(32) NOT NULL, model_version INTEGER NOT NULL, provider_revision VARCHAR(32) NOT NULL, status VARCHAR(20) NOT NULL, config JSON NOT NULL, result JSON NOT NULL, actor VARCHAR(32) NOT NULL, created_at VARCHAR(40) NOT NULL);
CREATE TABLE IF NOT EXISTS model_hub_invocations (id VARCHAR(64) PRIMARY KEY NOT NULL, actor VARCHAR(32) NOT NULL, operation VARCHAR(24) NOT NULL, request_digest VARCHAR(64) NOT NULL, status VARCHAR(24) NOT NULL, status_code INTEGER NOT NULL, response_body JSON NOT NULL, created_at VARCHAR(40) NOT NULL, finished_at VARCHAR(40) NOT NULL);
CREATE TABLE IF NOT EXISTS native_executions (id VARCHAR(64) PRIMARY KEY NOT NULL, run_id VARCHAR(32) NOT NULL, task_key VARCHAR(64) NOT NULL, fingerprint VARCHAR(64) NOT NULL, state VARCHAR(24) NOT NULL, result JSON NOT NULL, created_at VARCHAR(40) NOT NULL);
CREATE TABLE IF NOT EXISTS provider_catalog_model_states (id VARCHAR(32) PRIMARY KEY NOT NULL, provider_id VARCHAR(32) NOT NULL, retired BOOLEAN NOT NULL, updated_at VARCHAR(40) NOT NULL);
CREATE TABLE IF NOT EXISTS provider_catalog_pull_receipts (id VARCHAR(80) PRIMARY KEY NOT NULL, data JSON NOT NULL);
CREATE TABLE IF NOT EXISTS provider_model_catalogs (id VARCHAR(80) PRIMARY KEY NOT NULL, provider_id VARCHAR(32) NOT NULL, revision_id VARCHAR(32) NOT NULL, entries JSON NOT NULL, last_synced_at VARCHAR(40) NOT NULL, last_attempt_at VARCHAR(40) NOT NULL, error VARCHAR(500) NOT NULL, sync_token VARCHAR(32) NOT NULL);
CREATE TABLE IF NOT EXISTS skill_store_sources (id VARCHAR(32) PRIMARY KEY NOT NULL, config JSON NOT NULL, version INTEGER NOT NULL, enabled BOOLEAN NOT NULL, last_sync VARCHAR(40) NOT NULL, resolved_ref VARCHAR(100) NOT NULL, last_error TEXT NOT NULL, summary JSON NOT NULL);
CREATE TABLE IF NOT EXISTS skill_store_items (id VARCHAR(32) PRIMARY KEY NOT NULL, source_id VARCHAR(32) NOT NULL, path VARCHAR(500) NOT NULL, latest_revision VARCHAR(64) NOT NULL, available BOOLEAN NOT NULL, skill_id VARCHAR(32) NOT NULL, installed_version INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS skill_store_revisions (id VARCHAR(64) PRIMARY KEY NOT NULL, item_id VARCHAR(32) NOT NULL, files JSON NOT NULL, details JSON NOT NULL, origin JSON NOT NULL, digest VARCHAR(64) NOT NULL, created_at VARCHAR(40) NOT NULL);
CREATE TABLE IF NOT EXISTS skill_store_installs (revision_id VARCHAR(64) PRIMARY KEY NOT NULL, item_id VARCHAR(32) NOT NULL, skill_id VARCHAR(32) NOT NULL, skill_version INTEGER NOT NULL, digest VARCHAR(64) NOT NULL, created_at VARCHAR(40) NOT NULL);
CREATE TABLE IF NOT EXISTS tool_installations (id VARCHAR(64) PRIMARY KEY NOT NULL, run_id VARCHAR(32) NOT NULL, task_key VARCHAR(64) NOT NULL, agent_id VARCHAR(32) NOT NULL, decision_id VARCHAR(64) NOT NULL, digest VARCHAR(64) NOT NULL, manifest JSON NOT NULL, reason VARCHAR(2000) NOT NULL, status VARCHAR(24) NOT NULL, reviewed_by VARCHAR(32) NOT NULL, review_comment VARCHAR(2000) NOT NULL, result JSON NOT NULL, created_at VARCHAR(40) NOT NULL, updated_at VARCHAR(40) NOT NULL);
CREATE INDEX IF NOT EXISTS ix_design_assets_kind ON design_assets(kind);
CREATE INDEX IF NOT EXISTS ix_design_audit_asset_id ON design_audit(asset_id);
CREATE INDEX IF NOT EXISTS ix_design_revisions_asset_id ON design_revisions(asset_id);
CREATE INDEX IF NOT EXISTS ix_execution_permissions_run_id ON execution_permissions(run_id);
CREATE INDEX IF NOT EXISTS ix_model_asset_revisions_model_id ON model_asset_revisions(model_id);
CREATE INDEX IF NOT EXISTS ix_model_benchmarks_model_id ON model_benchmarks(model_id);
CREATE INDEX IF NOT EXISTS ix_model_hub_invocations_status ON model_hub_invocations(status);
CREATE INDEX IF NOT EXISTS ix_model_hub_invocations_actor ON model_hub_invocations(actor);
CREATE INDEX IF NOT EXISTS ix_native_executions_run_id ON native_executions(run_id);
CREATE INDEX IF NOT EXISTS ix_provider_catalog_model_states_provider_id ON provider_catalog_model_states(provider_id);
CREATE INDEX IF NOT EXISTS ix_provider_model_catalogs_provider_id ON provider_model_catalogs(provider_id);
CREATE INDEX IF NOT EXISTS ix_skill_store_installs_item_id ON skill_store_installs(item_id);
CREATE INDEX IF NOT EXISTS ix_skill_store_installs_skill_id ON skill_store_installs(skill_id);
CREATE INDEX IF NOT EXISTS ix_skill_store_items_source_id ON skill_store_items(source_id);
CREATE INDEX IF NOT EXISTS ix_skill_store_revisions_item_id ON skill_store_revisions(item_id);
CREATE INDEX IF NOT EXISTS ix_tool_installations_run_id ON tool_installations(run_id);
CREATE TABLE IF NOT EXISTS forge_team_runs (run_id TEXT PRIMARY KEY NOT NULL, snapshot JSON NOT NULL, snapshot_digest TEXT NOT NULL, status TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS forge_team_decision_callbacks (id TEXT PRIMARY KEY NOT NULL, run_id TEXT NOT NULL, task_key TEXT NOT NULL, agent_id TEXT NOT NULL, project_id TEXT NOT NULL, binding JSON NOT NULL, payload_digest TEXT NOT NULL, question_ids JSON NOT NULL, status TEXT NOT NULL, response JSON NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS ix_forge_team_decision_callbacks_run_id ON forge_team_decision_callbacks(run_id);
